'use strict';
let courseMaterials=[],courseJob=null,courseGenerated=null,coursePollTimer=null;
const legacyMaterialImport=importMaterial;
async function showCourseImporter(){
 if(courseGenerated){showCoursePreview();return;}
 modal(`<span class="eyebrow">带来教材，生成有顺序的学习之旅</span><h2 id="dialogTitle">把材料整理成四章，而不是一堆零散题目。</h2><p>支持多份 TXT、Markdown、CSV、JSON 文字材料，合计最多约7MB。后台分片整理基础知识、章节、小节与练习，生成后先核对，再加入小镇。PDF和扫描件请先提取文字。</p><label class="form-label" for="courseTitle">课程名称</label><input id="courseTitle" value="我的学习课程"><div id="courseDrop" class="course-drop-zone">把学习文件拖到这里<br><input id="courseFiles" type="file" multiple accept=".txt,.md,.csv,.json" aria-label="选择多份学习材料"></div><div id="courseFileList"></div><p id="courseAPIStatus" class="note">正在检查本机课程生成服务…</p><div id="courseJobStatus" class="course-progress" role="status" aria-live="polite"></div><div class="actions"><button id="generateCourse" class="primary" disabled>发送材料并生成课程</button><button id="cancelCourseJob" ${courseJob?'':'disabled'}>取消生成</button><button id="legacyMaterial">导入已有题库</button></div><p class="muted">点击生成后，所选文字会发送到你在本机配置的模型服务；不会把密钥放进网页。生成结果需核对，不会自动替换任何已有材料和进度。</p>`,true);
 $('courseFiles').onchange=e=>readCourseFiles(e.target.files);
 const drop=$('courseDrop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragover');};drop.ondragleave=()=>drop.classList.remove('dragover');drop.ondrop=e=>{e.preventDefault();e.stopPropagation();drop.classList.remove('dragover');readCourseFiles(e.dataTransfer.files);};
 $('legacyMaterial').onclick=legacyMaterialImport;$('cancelCourseJob').onclick=cancelGeneratedCourse;
 renderCourseFileList();
 try{const response=await fetch('/api/config');if(!response.ok)throw Error();const config=await response.json();if(!$('courseAPIStatus'))return;$('courseAPIStatus').textContent=config.configured?`生成服务：${config.service} · 模型 ${config.model}。每约 ${config.chunkChars} 字分片，最多 ${config.maxChunks} 次调用。`:'本机服务已启动，但尚未配置API。请在项目根目录的.env中填写服务地址、模型与密钥，重启服务后再试。';$('generateCourse').disabled=!config.configured||!!courseJob;$('generateCourse').onclick=startGeneratedCourse;if(courseJob)pollGeneratedCourse();}
 catch{if($('courseAPIStatus'))$('courseAPIStatus').textContent='当前是静态预览，无法调用课程API。请在项目目录运行 npm start，然后打开 http://127.0.0.1:8766。基础课程可以继续离线游玩。';}
}
async function readCourseFiles(fileList){const files=[...(fileList||[])];if(!files.length)return;if(files.length>50||files.reduce((n,f)=>n+f.size,0)>7*1024*1024){toast('每次最多50份文字文件、合计7MB，请按课程拆分。');return;}if(files.some(f=>! /\.(txt|md|csv|json)$/i.test(f.name))){toast('请先将PDF、图片或其他文件转成文字，再上传TXT、Markdown、CSV或JSON。');return;}try{courseMaterials=await Promise.all(files.map(async f=>({name:f.name,text:await f.text()})));renderCourseFileList();}catch{toast('读取材料失败，请重新选择文件。');}}
function renderCourseFileList(){if($('courseFileList'))$('courseFileList').innerHTML=courseMaterials.length?`<div class="note">已选择 ${courseMaterials.length} 份材料：${courseMaterials.map(m=>esc(m.name)).join('、')}</div>`:'';}
async function startGeneratedCourse(){if(courseJob)return;if(!courseMaterials.length){$('courseJobStatus').textContent='请先选择至少一份学习材料。';return;}$('generateCourse').disabled=true;$('courseJobStatus').textContent='正在提交课程生成任务…';try{const r=await fetch('/api/course-jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:$('courseTitle').value.trim()||'我的学习课程',materials:courseMaterials})}),data=await r.json();if(!r.ok)throw Error(data.error||'无法提交生成任务。');courseJob=data.id;if($('cancelCourseJob'))$('cancelCourseJob').disabled=false;pollGeneratedCourse();}catch(error){if($('courseJobStatus'))$('courseJobStatus').textContent=error.message;if($('generateCourse'))$('generateCourse').disabled=false;}}
async function pollGeneratedCourse(){clearTimeout(coursePollTimer);const id=courseJob;if(!id)return;try{const r=await fetch('/api/course-jobs/'+encodeURIComponent(id)),data=await r.json();if(courseJob!==id)return;if(!r.ok)throw Error(data.error||'读取任务失败。');if(data.status==='done'){courseGenerated=CourseSchema.normalize(data.course);courseJob=null;if($('courseJobStatus'))showCoursePreview();else toast('课程已整理好，可从“导入材料”打开预览并核对。');return;}if(['failed','cancelled'].includes(data.status))throw Error(data.error||'生成已取消。');if($('courseJobStatus'))$('courseJobStatus').textContent=`已完成 ${data.done}/${data.total||'…'} 个材料分片。正在组织基础知识、章节与练习…`;coursePollTimer=setTimeout(pollGeneratedCourse,1500);}catch(error){courseJob=null;if($('courseJobStatus'))$('courseJobStatus').textContent=error.message;if($('generateCourse'))$('generateCourse').disabled=false;}}
async function cancelGeneratedCourse(){clearTimeout(coursePollTimer);const id=courseJob;courseJob=null;if(id)try{await fetch('/api/course-jobs/'+encodeURIComponent(id),{method:'DELETE'});}catch{}if($('courseJobStatus'))$('courseJobStatus').textContent='已取消生成；原有课程与进度保持不变。';if($('generateCourse'))$('generateCourse').disabled=false;}
function showCoursePreview(){const course=courseGenerated;if(!course)return;modal(`<span class="eyebrow">课程预览 · 先核对再加入</span><h2 id="dialogTitle">${esc(course.title)}</h2><p>按章节检查基础解释、例子、练习及原文引用。AI整理可能出错；只有你确认后才创建新课程。</p><div class="course-preview">${course.chapters.map((ch,i)=>`<article><h3>第 ${i+1} 章 · ${esc(ch.title)}</h3>${ch.sections.map(sec=>`<details><summary>${esc(sec.id+' '+sec.title)} · ${sec.lessons.length} 张基础卡 / ${sec.questions.length} 题</summary>${sec.lessons.map(l=>`<details><summary>${esc(l.title)}</summary><p>${esc(l.body)}</p><p>${esc(l.example)}</p><blockquote>${esc(l.quote)}</blockquote><small>${esc(l.source)}</small></details>`).join('')}<details><summary>核对本节练习与答案</summary>${sec.questions.map(q=>`<div class="item-row"><strong>${esc(q.q)}</strong><p>${esc(learningAnswer(q))}</p><blockquote>${esc(q.quote)}</blockquote></div>`).join('')}</details></details>`).join('')}</article>`).join('')}</div><label class="form-label"><input id="confirmCourse" type="checkbox"> 我已核对内容、顺序与原文，确认加入为一门新课程。</label><div class="actions"><button id="discardCoursePreview">返回材料，不加入</button><button id="commitCourse" class="primary" disabled>加入课程，从第一章基础开始</button></div>`,true);$('confirmCourse').onchange=()=>{$('commitCourse').disabled=!$('confirmCourse').checked;};$('discardCoursePreview').onclick=()=>{courseGenerated=null;showCourseImporter();};$('commitCourse').onclick=()=>{try{const normalized=CourseSchema.normalize(course),b=L.addBank(state,{title:normalized.title,kind:'API整理 · 已由用户核对',cards:CourseSchema.cards(normalized)},Date.now());b.syllabus=normalized;b.focus=normalized.chapters[0].sections[0].id;state.chapterStudies??={};state.chapterStudies[b.id]=CS.fresh();L.start(state,Date.now(),true);A.session(state);activeQuest=null;selectedPiece=null;selectedTool=null;state.zone=normalized.chapters[0].zone;state.guide=true;courseGenerated=null;close();renderWorld();resetCamera();save();toast('课程已加入。可以自由选择章节；每章先阅读基础，再解锁本章练习。');}catch(error){toast(error.message);}};}
importMaterial=showCourseImporter;
document.addEventListener('dragover',e=>{if(e.dataTransfer?.types?.includes('Files'))e.preventDefault();});
document.addEventListener('drop',e=>{if(!e.dataTransfer?.files?.length)return;e.preventDefault();showCourseImporter();readCourseFiles(e.dataTransfer.files);});
